from streamlit.web.server.server_util import is_url_from_allowed_origins
from tornado.websocket import WebSocketHandler

class SecureWebSocketMiddleware:
    def __init__(self, app):
        self.app = app

    async def __call__(self, request):
        if request.headers.get('Upgrade', '').lower() == 'websocket':
            # Force secure WebSocket
            request.headers['X-Forwarded-Proto'] = 'https'
            if not request.url.startswith('wss://'):
                request.url = request.url.replace('ws://', 'wss://')

        return await self.app(request)

(function() {
    const originalWebSocket = window.WebSocket;
    window.WebSocket = function(url, protocols) {
        // Get the current page's full hostname (including subdomain)
        const fullHostname = window.location.hostname;

        // Create a new URL object to properly parse the WebSocket URL
        let wsUrl;
        try {
            wsUrl = new URL(url);
            // Always use the same hostname as the page and wss://
            wsUrl.protocol = 'wss:';
            wsUrl.host = fullHostname;
            url = wsUrl.toString();
        } catch (e) {
            console.error('Failed to parse WebSocket URL:', e);
        }

        console.log('WebSocket attempting connection to:', url);
        return new originalWebSocket(url, protocols);
    };
})();
